from rdkit import Chem
import numpy as np
s='C=C(C(C)=CN(c2c(C(C)C)cccc2C(C)C)[Si]1([Ge])([Ge]))N1(c1c(C(C)C)cccc1C(C)C)'
m=Chem.AddHs(Chem.MolFromSmiles(s)); bonded={tuple(sorted((b.GetBeginAtomIdx(),b.GetEndAtomIdx()))) for b in m.GetBonds()}
for z,ring0,me0,h0 in [(19,74,79,84),(20,99,104,109)]:
 for k in range(5):
  r=ring0+k; bonded.add(tuple(sorted((r,ring0+(k+1)%5))));bonded.add(tuple(sorted((r,me0+k))));bonded.add(tuple(sorted((z,r))))
  for q in range(3):bonded.add(tuple(sorted((me0+k,h0+3*k+q))))
ls=open('answer.xyz').read().splitlines()[2:];sy=[l.split()[0] for l in ls];x=np.array([[float(v) for v in l.split()[1:]] for l in ls])
close=[]
for i in range(len(sy)):
 for j in range(i+1,len(sy)):
  if (i,j) in bonded:continue
  d=np.linalg.norm(x[i]-x[j])
  # threshold by elements rough; list under 1.55
  if d<1.55:close.append((d,i,sy[i],j,sy[j]))
print('close nonbonded <1.55',len(close))
for row in sorted(close)[:50]:print(row)
# min overall nonbonded
print('min',min(close))
